    containerBg: "#f8fafc",
    textPrimary: "#0f172a",
    textSecondary: "#475569",
    textMuted: "#94a3b8",
    cardBg: "#ffffff",
    cardBorder: "#e2e8f0",
    cardShadow: "0 2px 10px rgba(0,0,0,0.06)",
    itemBg: "#ffffff",
    itemBorder: "#e2e8f0",
    itemHoverBg: "#f8fafc",
    petalBg: "#f1f5f9",
    petalStroke: "#cbd5e1",
    petalHoverStroke: "#0284c7",
    hubFill: "#ffffff",
    hubStroke: "#e2e8f0",
    hubPct: "#10b981",
    hubTitle: "#475569",
    hubSub: "#64748b",
    barTrack: "#e2e8f0",
    labelColor: "#0f172a",
    subLabelColor: "#475569",
    pillsBg: "#f1f5f9",
    pillsBorder: "#e2e8f0",
    pillInactiveText: "#64748b",
    pillActiveBg: "#2563eb",
    legendBg: "#ffffff",
